'use client'

import * as React from 'react'
import * as HoverCardPrimitive from '@radix-ui/react-hover-card'

import { cn } from '@/lib/utils'

function HoverCard({ ...props }: React.ComponentProps) {
    return (
        <HoverCardPrimitive.Root
            data-slot="hover-card"
            {...props}
        />
    )
}

function HoverCardTrigger({ ...props }: React.ComponentProps) {
    return (
        <HoverCardPrimitive.Trigger
            data-slot="hover-card-trigger"
            {...props}
        />
    )
}

function HoverCardContent({ className, align = 'center', sideOffset = 4, ...props }: React.ComponentProps) {
    return (
        <HoverCardPrimitive.Portal data-slot="hover-card-portal">
            <HoverCardPrimitive.Content
                data-slot="hover-card-content"
                align={align}
                sideOffset={sideOffset}
                className={cn(
                    'bg-popover text-popover-foreground data-[state=open]:animate-in data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0 data-[state=closed]:zoom-out-95 data-[state=open]:zoom-in-95 data-[side=bottom]:slide-in-from-top-2 data-[side=left]:slide-in-from-right-2 data-[side=right]:slide-in-from-left-2 data-[side=top]:slide-in-from-bottom-2 origin-(--radix-hover-card-content-transform-origin) outline-hidden rounded-(--radius) ring-foreground/10 z-50 w-64 border border-transparent p-4 shadow-md ring-1',
                    className
                )}
                {...props}
            />
        </HoverCardPrimitive.Portal>
    )
}

export { HoverCard, HoverCardTrigger, HoverCardContent }
